import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import {spawnSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
const root=path.resolve(import.meta.dirname,'..');
const parent=path.dirname(root);
const files=['SKILL.md','rules/quality-gates-2026.md','references/21st-dev-y-herramientas-2026.md','references/direccion-arte-agencia-premium.md','references/stack-y-pruebas-2026.md','orchestration/flow.md','orchestration/skill-routing.md'];
const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const render=s=>s.split(/\r?\n/).map(l=>{
 const h=l.match(/^(#{1,6})\s+(.+)/);
 if(h)return '<h'+Math.min(6,h[1].length+1)+'>'+esc(h[2])+'</h'+Math.min(6,h[1].length+1)+'>';
 if(l.trim()==='')return '<div class="space"></div>';
 if(/^\s*[-*] /.test(l))return '<p class="bullet">'+esc(l.trim().slice(2))+'</p>';
 if(/^\s*\d+[.)]\s/.test(l))return '<p class="bullet">'+esc(l.trim())+'</p>';
 if(l.trim().startsWith('|'))return '<p class="tab">'+esc(l)+'</p>';
 if(l.trim().startsWith(String.fromCharCode(96)))return '<p class="code">'+esc(l)+'</p>';
 return '<p>'+esc(l)+'</p>';
}).join('\n');
const parts=files.map((file,i)=>'<section><h1 class="section-title">'+String(i+1).padStart(2,'0')+' — '+esc(file)+'</h1>'+render(fs.readFileSync(path.join(root,file),'utf8'))+'</section>').join('\n');
const css='@page{size:A4;margin:17mm 17mm}body{font-family:Arial,Helvetica,sans-serif;color:#192434;background:#fff;font-size:10.5pt;line-height:1.5}header{padding:40pt 0 24pt;border-bottom:4pt solid #c3a45c;margin-bottom:20pt}header h1{font-size:39pt;line-height:1.02;letter-spacing:-1.2pt;margin:7pt 0;color:#121b2a}header .micro{letter-spacing:2pt;font-size:10pt;color:#8f712c;font-weight:bold}header p{font-size:12pt;max-width:480pt}h1.section-title{page-break-before:always;break-after:avoid;border-bottom:2pt solid #c3a45c;color:#8b6a2b;font-size:19pt;padding-bottom:8pt;margin-bottom:15pt}h2{font-size:15pt;color:#14213b;break-after:avoid;margin:20pt 0 8pt}h3{font-size:12.5pt;break-after:avoid;margin:14pt 0 6pt}h4,h5,h6{font-size:11pt;break-after:avoid;margin:11pt 0 5pt}p{margin:0 0 6pt;overflow-wrap:anywhere}.bullet{margin-left:14pt}.bullet:before{content:"• ";color:#b28d45}.space{height:3pt}.tab{font-family:Consolas,monospace;font-size:8pt;overflow-wrap:anywhere;background:#f5f7fa;padding:3pt;margin-bottom:1pt}.code{font-family:Consolas,monospace;color:#405069;background:#f6f6f7;font-size:9pt;overflow-wrap:anywhere}section{margin-bottom:20pt}';
const html='<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Prompt Maestro V8 Actualizado 2026</title><style>'+css+'</style></head><body><header><div class="micro">SISTEMA OPERATIVO · V8 · 23 OCT 2026</div><h1>PROMPT MAESTRO<br>V8</h1><p>Edición actualizada: dirección artística distintiva, experiencia interactiva funcional, producción moderna y pruebas verificables.</p><p><b>Sigue siendo V8.</b> Nueve fases y salida A–L originales.</p></header>'+parts+'</body></html>';
const htmlPath=path.join(parent,'PROMPT_MAESTRO_V8_ACTUALIZADO_2026.html');
const pdfPath=path.join(parent,'PROMPT_MAESTRO_V8_ACTUALIZADO_2026.pdf');
fs.writeFileSync(htmlPath,html,'utf8');
const chrome='C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const args=['--headless','--disable-gpu','--no-first-run','--no-sandbox','--user-data-dir='+path.join(os.tmpdir(),'v8pdf_'+process.pid),'--print-to-pdf-no-header','--print-to-pdf='+pdfPath,pathToFileURL(htmlPath).href];
const r=spawnSync(chrome,args,{encoding:'utf8',windowsHide:true,timeout:90000});
const ok=fs.existsSync(pdfPath)&&fs.statSync(pdfPath).size>10000;
console.log(JSON.stringify({status:ok?'PASS':'FAIL',pdf:pdfPath,bytes:ok?fs.statSync(pdfPath).size:0,chromeExit:r.status,stderr:(r.stderr||'').slice(-600)},null,2));
if(!ok)process.exitCode=1;